// Lowest Common Ancestor in a BST
let tree = AnimatedBinaryTree<Int>()
tree.insert(20)
tree.insert(8)
tree.insert(22)
tree.insert(4)
tree.insert(12)

let leftChild = [20: 8, 8: 4]
let rightChild = [20: 22, 8: 12]

func findLCA(p: Int, q: Int, t: AnimatedBinaryTree<Int>) -> Int? {
    var current = 20
    while true {
        t.search(current)
        if p < current && q < current {
            if let left = leftChild[current] {
                current = left
            } else {
                break
            }
        } else if p > current && q > current {
            if let right = rightChild[current] {
                current = right
            } else {
                break
            }
        } else {
            break
        }
    }
    return current
}

let lca = findLCA(p: 4, q: 12, t: tree)
